python3 -m pytest -q && python3 -c "
from sheet.engine import evaluate, CycleError
# spec spot-checks beyond the shipped tests
assert evaluate({'A': '=3/2'})['A'] == 1.5
assert evaluate({'A': '=-(B+1)', 'B': '2'})['A'] == -3.0
assert evaluate({'A': '= B1 + 1', 'B1': '2'})['A'] == 3.0
assert evaluate({'Z': '=A', 'A': '5'})['Z'] == 5.0  # forward ref
assert evaluate({'A': '=2*3+4/2-1'})['A'] == 7.0
for cells in [{'A': '=A'}, {'A': '=B', 'B': '=C', 'C': '=A'}]:
    try:
        evaluate(cells)
    except CycleError as e:
        print('CycleError ok:', e)
    else:
        raise AssertionError('no CycleError')
try:
    evaluate({'A': '=1/0'})
except ZeroDivisionError:
    print('ZeroDivisionError ok')
"

